    fn onCall(ctx: *anyopaque, peer: *rpc.peer.Peer, call: rpc.wire.protocol.Call, caps: *const rpc.caps.table.InboundCapTable) anyerror!void {
        const server: *Server = @ptrCast(@alignCast(ctx));
        switch (call.method_id) {
            OfferItems.ordinal => try OfferItems.handleCall(server, peer, call, caps),
            RemoveItems.ordinal => try RemoveItems.handleCall(server, peer, call, caps),
            Accept.ordinal => try Accept.handleCall(server, peer, call, caps),
            Confirm.ordinal => try Confirm.handleCall(server, peer, call, caps),
            Cancel.ordinal => try Cancel.handleCall(server, peer, call, caps),
            ViewOtherOffer.ordinal => try ViewOtherOffer.handleCall(server, peer, call, caps),
            GetState.ordinal => try GetState.handleCall(server, peer, call, caps),
            else => try peer.sendReturnException(call.question_id, "unknown method"),
        }
